peg4730650da5684e35417jpg4160211e9ab63c688c099a3b584cc0c7512.jpg", "label": {"de": "Haarpflege", "en": "Hair care"}, "href": "/c/hair-care", "color": "indigo"}, {"image": "https://cdn.selldone.com/app/shops/15718/categories/grl000095erzuli100naturalsheabutter16ozjpeg70d63eb7920795ad1d5afcb5cb6396e4jpg4e1adef3da5e3ad58cc3bee18e8e8377512.jpg", "label": {"de": "Hautpflege", "en": "Skin care"}, "href": "/c/skin-care", "color": "terra"}, {"image": "https://cdn.selldone.com/app/shops/15718/categories/grl000745ethiopianclayjebenacoffeepotwithdecorativegoldstandjpeg621d67c61514fe79jpg711331a7a8960ed0aab8e93c2f359326512.jpg", "label": {"de": "Kaffeezeremonie", "en": "Coffee ceremony"}, "href": "/c/coffee-ceremony", "color": "sand"}, {"image": "https://cdn.selldone.com/app/shops/15718/categories/grl000746traditionalterracottaclayjugjpeg29cfaee0e97a6d7289145000af3b80ddjpg8a21759f02d5631308f572b503c324a8512.jpg", "label": {"de": "Deko & Keramik", "en": "Décor & pottery"}, "href": "/c/decor", "color": "terra"}, {"image": "https://cdn.selldone.com/app/shops/15718/categories/grl000260allfood100cassavafufuflour1kgjpega8e8b65e75d10a2733b9ba0a58b2f42djpg3a75096c3601e59b7748d6344b0b3974512.jpg", "label": {"de": "Alle Lebensmittel", "en": "All groceries"}, "href": "/c/food", "color": "sand"}, {"image": "https://cdn.selldone.com/app/shops/15718/categories/grl000699sheamoisturejamaicanblackcastoroilstrengthenrestorecojpegf7e7e37c5e13d1jpg928436ba8b575c59d1887bb61c456eaf512.jpg", "label": {"de": "Alle Kosmetik", "en": "All beauty"}, "href": "/c/beauty", "color": "sand"}]}'::jsonb);
