insert into home_sections(type,position,enabled,data) values ('usp',70,true,'{"title": {"de": "Einkaufen bei Greenland", "en": "Shopping with Greenland"}, "items": [{"icon": "truck", "title": {"de": "Versand in ganz Deutschland", "en": "Delivery across Germany"}, "text": {"de": "DHL in 2–3 Werktagen, ab 69 € kostenlos.", "en": "DHL in 2–3 working days, free from €69."}}, {"icon": "bag", "title": {"de": "Kostenlos abholen", "en": "Free pickup"}, "text": {"de": "Online bestellen, im Laden in Kaiserslautern abholen.", "en": "Order online, collect at our Kaiserslautern shop."}}, {"icon": "snow", "title": {"de": "Tiefkühl-Express", "en": "Frozen express"}, "text": {"de": "Fisch und Fleisch in der Kühlbox, Lieferung am nächsten Tag.", "en": "Fish and meat in an insulated box, next-day delivery."}}, {"icon": "chat", "title": {"de": "Persönliche Beratung", "en": "Real people to talk to"}, "text": {"de": "Fragen zu einem Produkt? Schreib uns auf WhatsApp.", "en": "Questions about a product? Message us on WhatsApp."}}]}'::jsonb);
insert into home_sections(type,position,enabled,data) values ('products',80,true,'{"title": {"de": "Pflege für Haar & Haut", "en": "Hair & skin care"}, "text": {"de": "Cantu, Shea Moisture, ORS und natürliche Sheabutter.", "en": "Cantu, Shea Moisture, ORS and natural shea butter."}, "source": "category", "category": "beauty", "limit": 12, "color": "none"}'::jsonb);
insert into home_sections(type,position,enabled,data) values ('story',90,true,'{"image": "https://cdn.selldone.com/app/shops/15718/categories/grl000428ethiopiantraditionalporcelaincoffeesetwithgolddisplayjpeg952ea94bda4f19jpgc33db612f043b14de1a454ef37d5f88c512.jpg", "title": {"de": "Ein Laden für die Diaspora", "en": "A shop for the diaspora"}, "text": {"de": "Greenland Afro Asia Store ist ein Familienladen in Kaiserslautern. Wir führen die Zutaten und Pflegeprodukte, die du von zu Hause kennst, und das, was man in Deutschland nur schwer findet.\n\nKomm vorbei, probier etwas Neues oder schreib uns, wenn dir ein Produkt fehlt. Wir bestellen es gerne für dich.", "en": "Greenland Afro Asia Store is a family shop in Kaiserslautern. We stock the ingredients and care products you know from home, and the ones that are hard to find in Germany.\n\nDrop by, try something new, or message us if a product is missing. We are happy to order it in for you."}, "ctaLabel": {"de": "Mehr über uns", "en": "More about us"}, "ctaHref": "/info/ueber-uns", "imageSide": "left", "color": "sand"}'::jsonb);
insert into home_sections(type,position,enabled,data) values ('faq',100,true,'{"title": {"de": "Häufige Fragen", "en": "Questions people ask"}, "items": [{"q": {"de": "Wie lange dauert die Lieferung?", "en": "How long does delivery take?"}, "a": {"de": "Innerhalb Deutschlands 2–3 Werktage mit DHL. In Kaiserslautern und Umgebung liefern wir am selben oder nächsten Tag.", "en": "Within Germany 2–3 working days by DHL. In and around Kaiserslautern we deliver the same or next day."}}, {"q": {"de": "Kann ich Tiefkühlware bestellen?", "en": "Can I order frozen products?"}, "a": {"de": "Ja. Tiefkühlware versenden wir montags bis mittwochs per Express in einer isolierten Box. Mindestbestellwert 50 €.", "en": "Yes. Frozen products ship Monday to Wednesday by express in an insulated box. Minimum order €50."}}, {"q": {"de": "Kann ich im Laden abholen?", "en": "Can I pick up in store?"}, "a": {"de": "Ja, immer kostenlos. Wir schicken dir eine WhatsApp-Nachricht, sobald deine Bestellung bereit ist.", "en": "Yes, always free. We send you a WhatsApp message as soon as your order is ready."}}, {"q": {"de": "Ein Produkt fehlt. Könnt ihr es besorgen?", "en": "A product is missing. Can you get it?"}, "a": {"de": "Sehr gerne. Schreib uns auf WhatsApp, was du suchst.", "en": "Happily. Message us on WhatsApp with what you are looking for."}}]}'::jsonb);
insert into home_sections(type,position,enabled,data) values ('newsletter',110,true,'{"title": {"de": "Neue Ware und Angebote zuerst erfahren", "en": "Hear about new stock and offers first"}, "text": {"de": "Einmal im Monat, kein Spam.", "en": "Once a month, no spam."}, "buttonLabel": {"de": "Anmelden", "en": "Sign up"}, "note": {"de": "Du kannst dich jederzeit abmelden.", "en": "You can unsubscribe at any time."}, "color": "indigo"}'::jsonb);
insert into settings(key,value) values ('public.site','{"name": "Greenland Afro Asia Store", "tagline": {"de": "Afrikanische & asiatische Lebensmittel", "en": "African & Asian groceries"}, "announcements": [{"text": {"de": "Kostenloser Versand ab 69 €", "en": "Free delivery from €69"}}, {"text": {"de": "Kostenlose Abholung in Kaiserslautern", "en": "Free pickup in Kaiserslautern"}}, {"text": {"de": "Tiefkühlware per Express-Versand", "en": "Frozen goods by express delivery"}}], "whatsapp": "4915213945662", "phone": "0152 13945662", "email": "", "address": {"de": "Kaiserslautern, Deutschland", "en": "Kaiserslautern, Germany"}, "hours": {"de": "Mo–Sa 10–19 Uhr", "en": "Mon–Sat 10am–7pm"}, "about": {"de": "Afrikanische und asiatische Lebensmittel, Kosmetik und Deko aus Kaiserslautern.", "en": "African and Asian groceries, beauty and home goods from Kaiserslautern."}, "navLinks": [], "seoTitle": {"de": "Greenland Afro Asia Store – Afrikanische & asiatische Lebensmittel", "en": "Greenland Afro Asia Store – African & Asian groceries"}, "seoDescription": {"de": "Afrikanische und asiatische Lebensmittel, Kosmetik und Deko online kaufen. Versand in ganz Deutschland, Abholung in Kaiserslautern.", "en": "Buy African and Asian groceries, beauty and home goods online. Delivery across Germany, pickup in Kaiserslautern."}, "showWhatsappButton": true}'::jsonb) on conflict (key) do update set value=excluded.value;
insert into settings(key,value) values ('public.theme','{}'::jsonb) on conflict (key) do nothing;
insert into pages(slug,title,body,published,show_in_footer,sort) values ('lieferung','{"de": "Lieferung & Abholung", "en": "Delivery & pickup"}'::jsonb,'{"de": "## Standardversand (Deutschland)\nDHL, 2–3 Werktage, 5,99 €. Ab 69 € kostenlos.\n\n## EU-Versand\nÖsterreich, Niederlande, Belgien, Luxemburg, Frankreich: 4–6 Werktage, 14,99 €, ab 149 € kostenlos.\n\n## Tiefkühl-Express\nMontag bis Mittwoch in der Kühlbox, Zustellung am nächsten Werktag. 19,99 €, Mindestbestellwert 50 €.\n\n## Lokale Lieferung\nKaiserslautern und Umgebung, am selben oder nächsten Tag, 3,99 €, ab 40 € kostenlos.\n\n## Abholung\nOnline bestellen und im Laden abholen, immer kostenlos.", "en": "## Standard delivery (Germany)\nDHL, 2–3 working days, €5.99. Free from €69.\n\n## EU delivery\nAustria, Netherlands, Belgium, Luxembourg, France: 4–6 working days, €14.99, free from €149.\n\n## Frozen express\nMonday to Wednesday in an insulated box, next-working-day delivery. €19.99, minimum order €50.\n\n## Local delivery\nKaiserslautern and surroundings, same or next day, €3.99, free from €40.\n\n## Pickup\nOrder online and collect in store, always free."}'::jsonb,true,true,1) on conflict (slug) do update set title=excluded.title, body=excluded.body;
insert into pages(slug,title,body,published,show_in_footer,sort) values ('ueber-uns','{"de": "Über uns", "en": "About us"}'::jsonb,'{"de": "Greenland Afro Asia Store ist ein Familienladen in Kaiserslautern für afrikanische und asiatische Lebensmittel, Kosmetik und Deko.\n\nWir führen über 750 Produkte und bestellen gerne, was dir fehlt.", "en": "Greenland Afro Asia Store is a family shop in Kaiserslautern for African and Asian groceries, beauty and home goods.\n\nWe stock over 750 products and are happy to order in what you are missing."}'::jsonb,true,true,2) on conflict (slug) do update set title=excluded.title, body=excluded.body;
insert into pages(slug,title,body,published,show_in_footer,sort) values ('faq','{"de": "Häufige Fragen", "en": "FAQ"}'::jsonb,'{"de": "Die wichtigsten Antworten findest du auf der Startseite. Für alles andere schreib uns auf WhatsApp.", "en": "You''ll find the main answers on the home page. For anything else, message us on WhatsApp."}'::jsonb,true,true,3) on conflict (slug) do update set title=excluded.title, body=excluded.body;
